package org.jkiss.dbeaver.model.sql.completion;

import org.jkiss.code.NotNull;
import org.jkiss.code.Nullable;
import org.jkiss.dbeaver.model.DBPDataSource;
import org.jkiss.dbeaver.model.DBPImage;
import org.jkiss.dbeaver.model.DBPKeywordType;
import org.jkiss.dbeaver.model.DBPNamedObject;
import org.jkiss.dbeaver.model.exec.DBCExecutionContext;
import org.jkiss.dbeaver.model.preferences.DBPPreferenceStore;
import org.jkiss.dbeaver.model.sql.SQLSyntaxManager;
import org.jkiss.dbeaver.model.sql.parser.SQLRuleManager;

import java.util.Map;

public abstract class AbstractSQLCompletionContext implements SQLCompletionContext {
    private final DBPDataSource dataSource;
    private final DBCExecutionContext executionContext;
    private final SQLSyntaxManager syntaxManager;
    private final SQLRuleManager ruleManager;
    private final DBPPreferenceStore preferenceStore;

    protected AbstractSQLCompletionContext(
        @Nullable DBPDataSource dataSource,
        @Nullable DBCExecutionContext executionContext,
        @NotNull SQLSyntaxManager syntaxManager,
        @NotNull SQLRuleManager ruleManager,
        @NotNull DBPPreferenceStore preferenceStore
    ) {
        this.dataSource = dataSource;
        this.executionContext = executionContext;
        this.syntaxManager = syntaxManager;
        this.ruleManager = ruleManager;
        this.preferenceStore = preferenceStore;
    }

    @Nullable
    @Override
    public DBPDataSource getDataSource() {
        return dataSource;
    }

    @Nullable
    @Override
    public DBCExecutionContext getExecutionContext() {
        return executionContext;
    }

    @NotNull
    @Override
    public SQLSyntaxManager getSyntaxManager() {
        return syntaxManager;
    }

    @NotNull
    @Override
    public SQLRuleManager getRuleManager() {
        return ruleManager;
    }

    @NotNull
    @Override
    public DBPPreferenceStore getPreferenceStore() {
        return preferenceStore;
    }

    @Override
    public boolean isUseFQNames() {
        return false;
    }

    @Override
    public boolean isReplaceWords() {
        return false;
    }

    @Override
    public boolean isShowServerHelp() {
        return false;
    }

    @Override
    public boolean isUseShortNames() {
        return false;
    }

    @Override
    public int getInsertCase() {
        return PROPOSAL_CASE_DEFAULT;
    }

    @Override
    public boolean isSearchProcedures() {
        return false;
    }

    @Override
    public boolean isSearchInsideNames() {
        return false;
    }

    @Override
    public boolean isSortAlphabetically() {
        return false;
    }

    @Override
    public boolean isSearchGlobally() {
        return false;
    }

    @Override
    public boolean isHideDuplicates() {
        return false;
    }

    @Override
    public boolean isShowValues() {
        return false;
    }

    @Override
    public boolean isForceQualifiedColumnNames() {
        return false;
    }

    @NotNull
    @Override
    public SQLCompletionProposalBase createProposal(
        @NotNull SQLCompletionRequest request,
        @NotNull String displayString,
        @NotNull String replacementString,
        int cursorPosition,
        @Nullable DBPImage image,
        @NotNull DBPKeywordType proposalType,
        @Nullable String description,
        @Nullable DBPNamedObject object,
        @NotNull Map<String, Object> params
    ) {
        return new SQLCompletionProposalBase(
            request,
            displayString,
            replacementString,
            cursorPosition,
            image,
            proposalType,
            description,
            object,
            params
        );
    }
}

