 41	public class SQLCompletionProposalProviderTest extends DBeaverUnitTest {
 42	
 43	    @Test
 44	    public void legacyModeShouldProduceLegacyCompletionProposals()
 45	        throws DBException, InvocationTargetException, InterruptedException {
 46	        DBPPreferenceStore preferenceStore = mockPreferenceStore(SQLCompletionMode.DEFAULT, false, false);
 47	        SQLCompletionTestContext context = createCompletionContext(preferenceStore);
 48	
 49	        String sql = "SEL|";
 50	        int offset = sql.indexOf('|');
 51	        Document document = new Document(sql.replace("|", ""));
 52	        SQLCompletionRequest request = SQLCompletionRequestFactory.create(context, document, offset, false);
 53	
 54	        List<CompletionProposalBase> proposals = SQLCompletionProposalProvider.collectProposals(
 55	            new VoidProgressMonitor(),
 56	            request,
 57	            false
 58	        );
 59	
 60	        Assertions.assertFalse(proposals.isEmpty());
 61	        Assertions.assertEquals("SELECT", proposals.get(0).getReplacementString());
 62	    }
 63	
 64	    private static DBPPreferenceStore mockPreferenceStore(
 65	        SQLCompletionMode mode,
 66	        boolean advancedHighlightingEnabled,
 67	        boolean metadataReadEnabled
 68	    ) {
 69	        DBPPreferenceStore store = mock(DBPPreferenceStore.class);
 70	        when(store.getString(SQLModelPreferences.AUTOCOMPLETION_MODE)).thenReturn(mode.getPreferenceValue());
 71	        when(store.getBoolean(SQLModelPreferences.ADVANCED_HIGHLIGHTING_ENABLE)).thenReturn(advancedHighlightingEnabled);
 72	        when(store.getBoolean(SQLModelPreferences.READ_METADATA_FOR_SEMANTIC_ANALYSIS)).thenReturn(metadataReadEnabled);
 73	        return store;
 74	    }
 75	
 76	    private static SQLCompletionTestContext createCompletionContext(DBPPreferenceStore preferenceStore) {
 77	        DBPDataSourceContainer dataSourceContainer = mock(DBPDataSourceContainer.class);
 78	        when(dataSourceContainer.getPreferenceStore()).thenReturn(preferenceStore);
 79	
 80	        DBPDataSource dataSource = mock(DBPDataSource.class);
 81	        when(dataSource.getSQLDialect()).thenReturn(BasicSQLDialect.INSTANCE);
 82	        when(dataSource.getContainer()).thenReturn(dataSourceContainer);
 83	
 84	        DBCExecutionContext executionContext = mock(DBCExecutionContext.class);
 85	        when(executionContext.getDataSource()).thenReturn(dataSource);
 86	
 87	        SQLSyntaxManager syntaxManager = new SQLSyntaxManager();
 88	        syntaxManager.init(BasicSQLDialect.INSTANCE, preferenceStore);
 89	
 90	        SQLRuleManager ruleManager = new SQLRuleManager(syntaxManager);
 91	        ruleManager.loadRules(dataSource, false);
 92	
 93	        return new SQLCompletionTestContext(
 94	            dataSource,
 95	            executionContext,
 96	            syntaxManager,
 97	            ruleManager,
 98	            preferenceStore
 99	        );
100	    }
101	}

