44	        int offset = sql.indexOf('|');
45	        Document document = new Document(sql.replace("|", ""));
46	
47	        SQLCompletionRequest request = SQLCompletionRequestFactory.create(context, document, offset, false);
48	
49	        Assertions.assertNotNull(request.getActiveQuery());
50	        Assertions.assertEquals("SELECT 2", request.getActiveQuery().getText());
51	        Assertions.assertEquals(document.get().indexOf("SELECT 2"), request.getActiveQuery().getOffset());
52	    }
