 40	import java.util.Set;
 41	import java.util.stream.Collectors;
 42	
 43	import static org.mockito.Mockito.mock;
 44	import static org.mockito.Mockito.when;
 45	
 46	public class RequestResult {
 47	    private final DBPDataSource dataSource;
 48	
 49	    public RequestResult(@NotNull DBPDataSource dataSource) {
 50	        this.dataSource = dataSource;
 51	    }
 52	
 53	    @NotNull
 54	    public List<SQLCompletionProposalBase> request(@NotNull String sql) throws DBException {
 55	        return request(sql, true);
 56	    }
 57	
 58	    @NotNull
 59	    public List<SQLCompletionProposalBase> request(@NotNull String sql, boolean simpleMode) throws DBException {
 60	        final SQLCompletionRequest request = prepareCompletionRequest(sql, simpleMode);
 61	        return SQLCompletionAnalyzerSupport.collectLegacyProposals(new VoidProgressMonitor(), request, false);
 62	    }
 63	
 64	    /**
 65	     * Returns the list of proposals that semantic autocompletion engine returns for the provided text in simple mode
 66	     */
 67	    public Set<String> requestNewStrings(@NotNull String sql) throws DBException {
 68	        return this.requestNewStrings(sql, true);
 69	    }
 70	
 71	    /**
 72	     * Returns the list of proposals that semantic autocompletion engine returns for the provided text
 73	     */
 74	    public Set<String> requestNewStrings(@NotNull String sql, boolean simpleMode) throws DBException {
 75	        var r = this.requestNewInternal(sql, simpleMode);
 76	        return r.getSecond().stream().map(p -> {
 77	            try {
 78	                if (p.getReplacementLength() > 0) {
 79	                    String originalString = r.getFirst().getDocument().get(p.getReplacementOffset(), p.getReplacementLength());
 80	                    String replacementFragment = p.getReplacementString().substring(0, originalString.length());
 81	                    if (originalString.equals(replacementFragment) && replacementFragment.endsWith(".")) {
 82	                        return p.getReplacementString().substring(replacementFragment.length());
 83	                    } else {
 84	                        return p.getReplacementString();
 85	                    }
 86	                } else {
 87	                    return p.getReplacementString();
 88	                }
 89	            } catch (BadLocationException e) {
 90	                throw new RuntimeException(e);
 91	            }
 92	        }).collect(Collectors.toSet());
 93	    }
 94	
 95	    @NotNull
 96	    private Pair<SQLCompletionRequest, List<? extends SQLQueryCompletionProposal>> requestNewInternal(
 97	        @NotNull String sql,
 98	        boolean simpleMode
 99	    ) throws DBException {
100	        final SQLCompletionRequest request = prepareCompletionRequest(sql, simpleMode);
101	        final DBRProgressMonitor monitor = new VoidProgressMonitor();
102	        try {
103	            return Pair.of(
104	                request,
105	                SQLCompletionAnalyzerSupport.collectSemanticProposals(
106	                    monitor,
107	                    progressMonitor -> SQLQueryCompletionContextProvider.prepareCompletionContext(progressMonitor, request),
108	                    request,
109	                    request::getDocumentOffset
110	                )
111	            );
112	        } catch (InvocationTargetException | InterruptedException e) {
113	            throw new DBException("Error while preparing completion proposals", e);
114	        }
115	    }
116	
117	    @NotNull
118	    private SQLCompletionRequest prepareCompletionRequest(@NotNull String sql, boolean simpleMode) {
119	        final DBCExecutionContext executionContext = mock(DBCExecutionContext.class);
120	        when(executionContext.getDataSource()).thenReturn(dataSource);
121	
122	        final SQLSyntaxManager syntaxManager = new SQLSyntaxManager();
123	        syntaxManager.init(dataSource.getSQLDialect(), dataSource.getContainer().getPreferenceStore());
124	
125	        final SQLRuleManager ruleManager = new SQLRuleManager(syntaxManager);
126	        ruleManager.loadRules(dataSource, false);
127	
128	        final Pair<String, Integer> cursor = getCursorFromQuery(sql);
129	
130	        final Document document = new Document();
131	        document.set(cursor.getFirst());
132	
133	        final SQLCompletionTestContext context = new SQLCompletionTestContext(
134	            dataSource,
135	            executionContext,
136	            syntaxManager,
137	            ruleManager,
138	            dataSource.getContainer().getPreferenceStore(),
139	            true
140	        );
141	
142	        return SQLCompletionRequestFactory.create(
143	            context,
144	            document,
145	            cursor.getSecond(),
146	            simpleMode
147	        );
148	    }
149	
150	    @NotNull
151	    private static Pair<String, Integer> getCursorFromQuery(@NotNull String sql) {
152	        final int cursor = sql.indexOf('|');
153	        if (cursor < 0) {
154	            throw new IllegalArgumentException("Can't locate cursor in query");
155	        }
156	        return new Pair<>(sql.substring(0, cursor) + sql.substring(cursor + 1), cursor);
157	    }
158	}

